#include "engine/millennium_dos_fifth_function_session.hpp"
#include <stdexcept>
namespace eon {
MillenniumDosFifthFunctionSession::MillenniumDosFifthFunctionSession(std::span<const std::uint8_t> x):trace_(parse_millennium_dos_game_flow(x).fifth_function_key){if(trace_.handler_address!=0x7597||trace_.transfer_al_value!=2||trace_.first_call_address!=0xbe28||trace_.second_call_address!=0x0b9d||trace_.third_call_address!=0x4bf7||trace_.fourth_call_address!=0x0b76)throw std::runtime_error("Unsupported Millennium DOS fifth-function profile");}
MillenniumDosFifthFunctionBoundary MillenniumDosFifthFunctionSession::boundary()const{switch(state_){case MillenniumDosFifthFunctionState::first_call:return{MillenniumDosFifthFunctionBoundaryKind::call_return,0x7599,trace_.first_call_address,trace_.transfer_al_value};case MillenniumDosFifthFunctionState::second_call:return{MillenniumDosFifthFunctionBoundaryKind::call_return,0x759c,trace_.second_call_address,std::nullopt};case MillenniumDosFifthFunctionState::third_call:return{MillenniumDosFifthFunctionBoundaryKind::call_return,0x759f,trace_.third_call_address,std::nullopt};case MillenniumDosFifthFunctionState::fourth_call:return{MillenniumDosFifthFunctionBoundaryKind::call_return,0x75a2,trace_.fourth_call_address,std::nullopt};case MillenniumDosFifthFunctionState::returned:return{MillenniumDosFifthFunctionBoundaryKind::local_return,0x75a5,std::nullopt,std::nullopt};}throw std::runtime_error("Unsupported fifth-function state");}
void MillenniumDosFifthFunctionSession::observe_call_return(std::uint16_t c,std::uint16_t r){auto b=boundary();if(b.kind!=MillenniumDosFifthFunctionBoundaryKind::call_return||b.instruction_address!=c||r!=static_cast<std::uint16_t>(c+3U))throw std::runtime_error("Detached fifth-function return");state_=static_cast<MillenniumDosFifthFunctionState>(static_cast<int>(state_)+1);}
} // namespace eon
